95	    for(int i=5; i < 10; ++i) {
96	      assertEquals("i = "+ i, 5, VectoredReadUtils.roundDown(i, 5));
97	      assertEquals("i = "+ i, 10, VectoredReadUtils.roundUp(i+1, 5));
98	    }
99	    assertEquals("Error while roundDown", 13, VectoredReadUtils.roundDown(13, 1));
100	    assertEquals("Error while roundUp", 13, VectoredReadUtils.roundUp(13, 1));
101	  }
