+-  @Test
+-  public void testSortAndMerge() {
+-    List<FileRange> input = Arrays.asList(
+-        FileRange.createFileRange(3000, 100, "1"),
+-        FileRange.createFileRange(2100, 100, null),
+-        FileRange.createFileRange(1000, 100, "3")
